#include "sparse_branch_machine.hpp"
#include <charconv>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string_view>
namespace {template<class T>T number(std::string_view s,const char*n){T v{};auto[p,e]=std::from_chars(s.data(),s.data()+s.size(),v);if(e!=std::errc{}||p!=s.data()+s.size())throw std::invalid_argument(std::string("invalid ")+n);return v;}void usage(){std::cout<<"sbm_benchmark [--length N] [--warmup N] [--seed N] [--alphabet N] [--vector-dim N] [--hidden-dim N] [--dataset FILE] [--write-dataset FILE] [--prefill N] [--prune-interval N] [--merge-interval N] [--allow-eval-growth] [--output FILE]\n";}}
int main(int argc,char**argv){try{std::size_t length=120000,warmup=40000,prefill=0,pi=0,mi=0;std::uint64_t seed=7;std::uint32_t alphabet=64,vdim=16,hdim=24;bool strict=true;std::string dp,wdp,outp="results_vector_v4.json";for(int i=1;i<argc;++i){std::string_view a(argv[i]);if(a=="--help"||a=="-h"){usage();return 0;}if(a=="--allow-eval-growth"){strict=false;continue;}if(i+1>=argc)throw std::invalid_argument("missing value");std::string_view v(argv[++i]);if(a=="--length")length=number<std::size_t>(v,"length");else if(a=="--warmup")warmup=number<std::size_t>(v,"warmup");else if(a=="--seed")seed=number<std::uint64_t>(v,"seed");else if(a=="--alphabet")alphabet=number<std::uint32_t>(v,"alphabet");else if(a=="--vector-dim")vdim=number<std::uint32_t>(v,"vector-dim");else if(a=="--hidden-dim")hdim=number<std::uint32_t>(v,"hidden-dim");else if(a=="--prefill")prefill=number<std::size_t>(v,"prefill");else if(a=="--prune-interval")pi=number<std::size_t>(v,"prune-interval");else if(a=="--merge-interval")mi=number<std::size_t>(v,"merge-interval");else if(a=="--dataset")dp=v;else if(a=="--write-dataset")wdp=v;else if(a=="--output")outp=v;else throw std::invalid_argument("unknown argument");}auto d=dp.empty()?sbm::generate_vector_process(length,alphabet,vdim,hdim,seed):sbm::load_dataset(dp);if(!wdp.empty())sbm::save_dataset(d,wdp);auto r=sbm::run_experiment(d,warmup,seed,strict,prefill,pi,mi);auto j=sbm::to_json(r);std::ofstream o(outp);if(!o)throw std::runtime_error("cannot open output");o<<j;std::cout<<j;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}}
